function Show-WinUtilMaxSplash {
    [CmdletBinding()]
    param([int]$DurationMs = 1500)
    try {
        Add-Type -AssemblyName PresentationCore -ErrorAction SilentlyContinue
        Add-Type -AssemblyName PresentationFramework -ErrorAction SilentlyContinue
        Add-Type -AssemblyName WindowsBase -ErrorAction SilentlyContinue
        $image = $null
        $localCandidates = @((Join-Path (Get-Location).Path 'MAX.jpg'))
        if (-not [string]::IsNullOrWhiteSpace($PSScriptRoot)) { $localCandidates = @((Join-Path $PSScriptRoot '..\..\MAX.jpg')) + $localCandidates }
        foreach ($candidate in $localCandidates) {
            if (-not [string]::IsNullOrWhiteSpace($candidate) -and (Test-Path -LiteralPath $candidate -ErrorAction SilentlyContinue)) {
                try {
                    $uri = New-Object System.Uri((Resolve-Path -LiteralPath $candidate).Path)
                    $img = New-Object Windows.Media.Imaging.BitmapImage
                    $img.BeginInit()
                    $img.UriSource = $uri
                    $img.CacheOption = [Windows.Media.Imaging.BitmapCacheOption]::OnLoad
                    $img.EndInit()
                    if ($img.CanFreeze) { $img.Freeze() }
                    $image = $img
                    break
                } catch {}
            }
        }
        if ($null -eq $image) {
            $b64 = @'

'@
            try {
                $bytes = [Convert]::FromBase64String($b64)
                $ms = New-Object System.IO.MemoryStream(,$bytes)
                $img = New-Object Windows.Media.Imaging.BitmapImage
                $img.BeginInit()
                $img.StreamSource = $ms
                $img.CacheOption = [Windows.Media.Imaging.BitmapCacheOption]::OnLoad
                $img.EndInit()
                if ($img.CanFreeze) { $img.Freeze() }
                $image = $img
            } catch {}
        }
        if ($null -eq $image) { return }
        $splashXaml = '<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Title="winutil-MAX" Width="400" Height="460" WindowStyle="None" AllowsTransparency="True" Background="Transparent" WindowStartupLocation="CenterScreen" Topmost="True" ShowInTaskbar="False"><Border CornerRadius="18" BorderBrush="#ff007f" BorderThickness="2" ClipToBounds="True" Background="#121216"><Border.Effect><DropShadowEffect Color="#ff007f" BlurRadius="25" ShadowDepth="0" Opacity="0.6"/></Border.Effect><Grid><Image Name="SplashImage" Stretch="UniformToFill" VerticalAlignment="Top" Height="360"/><Border VerticalAlignment="Bottom" Height="150"><Border.Background><LinearGradientBrush StartPoint="0,0" EndPoint="0,1"><GradientStop Color="#00000000" Offset="0.0"/><GradientStop Color="#dd121216" Offset="0.4"/><GradientStop Color="#ff121216" Offset="1.0"/></LinearGradientBrush></Border.Background><StackPanel VerticalAlignment="Bottom" Margin="20,0,20,18" HorizontalAlignment="Center"><TextBlock Text="WINUTIL - MAX" FontSize="24" FontWeight="Bold" Foreground="#ffffff" HorizontalAlignment="Center" FontFamily="Segoe UI"><TextBlock.Effect><DropShadowEffect Color="#ff007f" BlurRadius="10" ShadowDepth="0" Opacity="0.8"/></TextBlock.Effect></TextBlock><TextBlock Text="Running Up That Hill" FontSize="13" FontStyle="Italic" Foreground="#ff77aa" HorizontalAlignment="Center" Margin="0,2,0,10" FontFamily="Segoe UI"/><ProgressBar IsIndeterminate="True" Height="4" Width="260" Foreground="#ff007f" Background="#333340" BorderThickness="0"/></StackPanel></Border></Grid></Border></Window>'
        [xml]$parsedXml = $splashXaml
        $reader = New-Object System.Xml.XmlNodeReader $parsedXml
        $splashWindow = [Windows.Markup.XamlReader]::Load($reader)
        $splashImgControl = $splashWindow.FindName('SplashImage')
        if ($splashImgControl) { $splashImgControl.Source = $image }
        $timer = New-Object System.Windows.Threading.DispatcherTimer
        $timer.Interval = [TimeSpan]::FromMilliseconds($DurationMs)
        $timer.Add_Tick({
            $timer.Stop()
            $splashWindow.Close()
        })
        $timer.Start()
        $splashWindow.ShowDialog() | Out-Null
    } catch {
        Write-WinUtilLog -Component 'UI' -Message "Splash screen note: $($_.Exception.Message)"
    }
}
